#include <cstddef>
#include <stdexcept>
#include <string>
#include <vector>

bool IsCyclicShift(const std::string& base, const std::string& candidate) {
    const std::size_t kMaxBytes = 100000;
    if (base.size() > kMaxBytes || candidate.size() > kMaxBytes)
        throw std::invalid_argument("input exceeds 100000 bytes");
    for (unsigned char ch : base)
        if (ch < 'A' || ch > 'Z')
            throw std::invalid_argument("base must be ASCII A-Z");
    for (unsigned char ch : candidate)
        if (ch < 'A' || ch > 'Z')
            throw std::invalid_argument("candidate must be ASCII A-Z");

    const std::size_t n = base.size();
    if (n != candidate.size()) return false;
    if (n == 0) return true;

    std::vector<std::size_t> prefix(n, 0);
    for (std::size_t i = 1, matched = 0; i < n; ++i) {
        while (matched > 0 && candidate[i] != candidate[matched])
            matched = prefix[matched - 1];
        if (candidate[i] == candidate[matched]) ++matched;
        prefix[i] = matched;
    }

    std::size_t matched = 0;
    for (std::size_t i = 0; i < 2 * n - 1; ++i) {
        const char ch = base[i % n];
        while (matched > 0 && ch != candidate[matched])
            matched = prefix[matched - 1];
        if (ch == candidate[matched]) ++matched;
        if (matched == n) return true;
    }
    return false;
}
